package dev.kantobridge.builder.shape;

import static org.junit.jupiter.api.Assertions.*;
import static dev.kantobridge.builder.shape.EmeraldInteriorSourceProofTest.*;
import com.google.gson.*;
import dev.kantobridge.builder.export.ExportBundle;
import dev.kantobridge.builder.plan.*;
import dev.kantobridge.scene.*;
import dev.kantobridge.world.MapLayout;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

/** Exact exported-map boundaries for opted-in terrain preservation and nearby source props. */
class EmeraldTerrainInterfaceProofTest {
    static final Path LIVE=ROOT.resolve("fabric-bridge/src/main/resources/kantobridge/fitted_shapes/emerald.json");
    @AfterEach void reset(){FittedShapes.useForTest(null);FittedShapes.useTablesForTest(null);FittedShapes.setEnabled(true);}
    static MapLayout layout(String name)throws Exception{var bundle=ExportBundle.open(ROOT.resolve("local/minecraft/kantobridge/export/emerald"));var built=G3Built.map(bundle,name);return RaisedRegions.gen3(G3Cells.model(built,bundle.g3tiles(built.pair()),true,new Warnings()),built,true).layout();}
    static JsonObject overlay(JsonObject before,JsonObject patch){var table=before.deepCopy();for(var e:patch.getAsJsonObject("cells").entrySet())table.getAsJsonObject("cells").add(e.getKey(),e.getValue());if(patch.has("buildings"))for(var e:patch.getAsJsonObject("buildings").entrySet())table.getAsJsonArray("buildings").add(e.getValue());return table;}
    static void equalColumn(ShapePlanner.MapShapes before,ShapePlanner.MapShapes after,int i){assertEquals(before.blocks()[i],after.blocks()[i],"blocks column "+i);assertEquals(before.shapeMask()[i],after.shapeMask()[i]);assertEquals(before.decor()[i],after.decor()[i]);assertEquals(before.floor()[i],after.floor()[i]);assertArrayEquals(before.open()[i],after.open()[i],"shape column "+i);assertArrayEquals(before.hung()[i],after.hung()[i]);assertEquals(before.hungMask()[i],after.hungMask()[i]);assertEquals(before.hungLeaves()[i],after.hungLeaves()[i]);}

    @Test void completeTrainerAndStationContextsIncludeActualNativeFloorsAndTemplates()throws Exception{
        var source=EmeraldSourceStackFollowupsTest.source();JsonObject baseline=read(ROOT.resolve("local/model-gallery/emerald-full-pass-baseline.json")),current=read(LIVE);String tableHash=sha(Files.readAllBytes(LIVE));JsonArray rows=new JsonArray();
        String[] names={"EM_ROUTE111","EM_ROUTE112"},ids={"emerald_trainer_hill_native_context","emerald_route112_lower_cable_station_native_context"};int[][] rects={{28,104,7,11},{26,22,8,7}};
        for(int j=0;j<names.length;j++){SceneMap map=source.scene().map(names[j]);var levels=layout(map.id());var before=EmeraldSourceStackFollowupsTest.plan(map,source,baseline,true,levels);var after=EmeraldSourceStackFollowupsTest.plan(map,source,current,true,levels);int[] r=rects[j];JsonObject row=rectangle(map,r[0],r[1],r[2],r[3],before,after);row.addProperty("id",ids[j]);var floors=sourceFloors(map,r[0],r[1],r[2],r[3],before,after,levels,null);assertEquals(r[2]*r[3]*4,floors.size());for(var f:floors)assertEquals(0,f.getAsJsonObject().get("feet").getAsInt(),"These two contexts are source-proven flat; no underfloor fill is omitted");row.add("source_floor_columns",floors);
            JsonArray templates=new JsonArray();for(var t:after.templates())if(t.x0()<2*(r[0]+r[2])&&t.y0()<2*(r[1]+r[3])&&t.x0()+t.entry().get("w").getAsInt()>2*r[0]&&t.y0()+t.entry().get("d").getAsInt()>2*r[1]){JsonObject p=new JsonObject();p.addProperty("sig",t.sig());p.addProperty("x0",t.x0());p.addProperty("y0",t.y0());p.add("entry",t.entry());templates.add(p);}assertEquals(1,templates.size());row.add("current_templates",templates);rows.add(row);
        }
        assertEquals(tableHash,sha(Files.readAllBytes(LIVE)));Path out=STUDY.resolve("terrain-building-contexts");Files.createDirectories(out);Files.copy(LIVE,out.resolve("fitted-proof-current.json"),StandardCopyOption.REPLACE_EXISTING);JsonObject proof=new JsonObject();proof.addProperty("original_baseline_sha256",sha(Files.readAllBytes(ROOT.resolve("local/model-gallery/emerald-full-pass-baseline.json"))));proof.addProperty("current_table_sha256",tableHash);proof.add("occurrences",rows);EmeraldSourceStackFollowupsTest.save("terrain-building-contexts/runtime-proof.json",proof);
    }

    @Test void fortreeCompleteForestRunsRecordActualSourceCarrierHeights()throws Exception{
        var source=EmeraldSourceStackFollowupsTest.source();var baseline=read(ROOT.resolve("local/model-gallery/emerald-full-pass-baseline.json"));var current=read(LIVE);JsonArray rows=new JsonArray();String[] maps={"EM_ROUTE119","EM_ROUTE119","EM_ROUTE120","EM_ROUTE119","EM_ROUTE120"};String[] ids={"west","east","center","hedge","hedge_cliff"};int[][] rects={{0,37,2,7},{5,40,2,11},{8,19,2,7},{4,0,4,3},{29,81,3,5}};
        for(int j=0;j<maps.length;j++){SceneMap map=source.scene().map(maps[j]);var levels=layout(map.id());var before=EmeraldSourceStackFollowupsTest.plan(map,source,baseline,true,levels);var after=EmeraldSourceStackFollowupsTest.plan(map,source,current,true,levels);int[] r=rects[j];JsonObject row=rectangle(map,r[0],r[1],r[2],r[3],before,after);row.addProperty("id",ids[j]);JsonArray columns=new JsonArray();for(int z=0;z<r[3]*2;z++)for(int x=0;x<r[2]*2;x++){int tx=r[0]*2+x,ty=r[1]*2+z,i=ty*map.artCols()+tx;JsonObject c=new JsonObject();c.addProperty("x",x);c.addProperty("z",z);c.addProperty("kind",map.kindAtTile(tx,ty).name());c.addProperty("blocks",after.blocks()[i]);c.addProperty("decor",after.decor()[i]);c.addProperty("feet",levels==null?0:levels.level(tx/2,ty/2));c.addProperty("keys",Arrays.toString(after.open()[i]));columns.add(c);}row.add("current_carriers",columns);rows.add(row);}
        Path out=STUDY.resolve("fortree-native-repairs");Files.createDirectories(out);JsonObject proof=new JsonObject();proof.addProperty("original_baseline_sha256",sha(Files.readAllBytes(ROOT.resolve("local/model-gallery/emerald-full-pass-baseline.json"))));proof.addProperty("current_table_sha256",sha(Files.readAllBytes(LIVE)));proof.add("occurrences",rows);EmeraldSourceStackFollowupsTest.save("fortree-native-repairs/full-forest-routing-proof.json",proof);
    }

    @Test void trainerOptInPreservesEveryUnclaimedColumnAgainstTheLiveTable()throws Exception{
        var source=EmeraldSourceStackFollowupsTest.source();SceneMap map=source.scene().map("EM_ROUTE111");var levels=layout(map.id());Path folder=STUDY.resolve("building-trainer-hill");JsonObject base=read(LIVE),patch=read(folder.resolve("updates.json")),candidate=overlay(base,patch),spec=patch.getAsJsonObject("buildings").getAsJsonObject("emerald_object_route111_trainer_hill");assertTrue(spec.get("preserveTerrain").getAsBoolean());
        byte[] kinds=map.kinds().clone();int[] tags=map.tags().clone(),tiles=map.tiles().clone();var swaps=List.copyOf(map.swapSites());
        var before=EmeraldSourceStackFollowupsTest.plan(map,source,base,true,levels);var after=EmeraldSourceStackFollowupsTest.plan(map,source,candidate,true,levels);assertEquals(before.templates().size()+1,after.templates().size());Set<String> excluded=new HashSet<>();for(var p:spec.getAsJsonArray("terrain")){var a=p.getAsJsonArray();excluded.add(a.get(0).getAsInt()+","+a.get(1).getAsInt());}int checked=0;
        for(int y=0;y<map.artRows();y++)for(int x=0;x<map.artCols();x++){int localX=x/2-29,localY=y/2-105;boolean claimed=localX>=0&&localX<5&&localY>=0&&localY<9&&!excluded.contains(localX+","+localY);if(!claimed){equalColumn(before,after,y*map.artCols()+x);checked++;}}
        assertArrayEquals(kinds,map.kinds());assertArrayEquals(tags,map.tags());assertArrayEquals(tiles,map.tiles());assertEquals(swaps,map.swapSites());
        // An unmatched opt-in cannot change another map's existing claims or native columns.
        SceneMap other=source.scene().map("EM_ROUTE110");var otherLayout=layout(other.id());var oldOther=EmeraldSourceStackFollowupsTest.plan(other,source,base,true,otherLayout);var newOther=EmeraldSourceStackFollowupsTest.plan(other,source,candidate,true,otherLayout);for(int i=0;i<oldOther.blocks().length;i++)equalColumn(oldOther,newOther,i);assertEquals(oldOther.templates(),newOther.templates());
        JsonObject proof=rectangle(map,28,104,7,11,before,after);proof.addProperty("unclaimed_columns_checked",checked);proof.addProperty("unmatched_map_columns_checked",oldOther.blocks().length);proof.addProperty("current_table_sha256",sha(Files.readAllBytes(LIVE)));proof.addProperty("candidate_updates_sha256",sha(Files.readAllBytes(folder.resolve("updates.json"))));JsonArray rows=new JsonArray();rows.add(proof);saveAt("building-trainer-hill/live-terrain-preservation-proof.json",rows);Files.copy(LIVE,folder.resolve("fitted-proof-current.json"),StandardCopyOption.REPLACE_EXISTING);
    }

    @Test void lowerCableStationKeepsExcludedConiferAndBothDoorWarps()throws Exception{
        new EmeraldInteriorSourceProofTest().mauvilleBuildings("building-route112-cable-station",1,6,0,2);
        var source=EmeraldSourceStackFollowupsTest.source();SceneMap map=source.scene().map("EM_ROUTE112");var levels=layout(map.id());Path folder=STUDY.resolve("building-route112-cable-station");var base=read(LIVE);var candidate=overlay(base,read(folder.resolve("updates.json")));var before=EmeraldSourceStackFollowupsTest.plan(map,source,base,true,levels);var after=EmeraldSourceStackFollowupsTest.plan(map,source,candidate,true,levels);
        // The source-excluded tree and its northern conifer partner must retain actual routing.
        for(int y=22;y<=23;y++)for(int z=0;z<2;z++)for(int x=0;x<2;x++)equalColumn(before,after,index(map,32,y,x,z));
        var original=EmeraldSourceStackFollowupsTest.plan(map,source,read(ROOT.resolve("local/model-gallery/emerald-full-pass-baseline.json")),true,levels);JsonObject proof=rectangle(map,26,22,8,7,original,after);proof.addProperty("id","emerald_route112_lower_cable_station_native_context");proof.addProperty("current_table_sha256",sha(Files.readAllBytes(LIVE)));proof.addProperty("candidate_updates_sha256",sha(Files.readAllBytes(folder.resolve("updates.json"))));JsonArray templates=new JsonArray();for(var t:after.templates())if(t.x0()==54&&t.y0()==46){JsonObject p=new JsonObject();p.addProperty("sig",t.sig());p.addProperty("x0",t.x0());p.addProperty("y0",t.y0());p.add("entry",t.entry());templates.add(p);}proof.add("current_templates",templates);JsonArray rows=new JsonArray();rows.add(proof);saveAt("building-route112-cable-station/native-context-proof.json",rows);
    }

    @Test void sandBathFalseStackRemovalKeepsEveryNativeWalkFloor()throws Exception{
        var source=EmeraldSourceStackFollowupsTest.source();SceneMap map=source.scene().map("EM_LAVARIDGE_TOWN");var levels=layout(map.id());Path folder=STUDY.resolve("towns-lavaridge-garden");JsonObject base=read(LIVE),patch=read(folder.resolve("updates.json")),candidate=overlay(base,patch);var before=EmeraldSourceStackFollowupsTest.plan(map,source,base,true,levels);var after=EmeraldSourceStackFollowupsTest.plan(map,source,candidate,true,levels);byte[] kinds=map.kinds().clone();int[] tags=map.tags().clone();var swaps=List.copyOf(map.swapSites());
        JsonArray rows=new JsonArray();for(int x:List.of(3,5)){for(int y=8;y<=9;y++){assertEquals(CellKind.WALK,map.kind(x,y));for(int dz=0;dz<2;dz++)for(int dx=0;dx<2;dx++){int i=index(map,x,y,dx,dz);equalColumn(before,after,i);assertEquals(0,after.blocks()[i]);assertEquals(0,after.decor()[i]);assertNull(after.open()[i]);}}JsonObject proof=rectangle(map,x,8,1,2,before,after);proof.add("source_floor_columns",sourceFloors(map,x,8,1,2,before,after,levels,null));rows.add(proof);}
        for(int i=0;i<before.blocks().length;i++)equalColumn(before,after,i);assertArrayEquals(kinds,map.kinds());assertArrayEquals(tags,map.tags());assertEquals(swaps,map.swapSites());JsonObject report=new JsonObject();report.addProperty("original_baseline_sha256",sha(Files.readAllBytes(ROOT.resolve("local/model-gallery/emerald-full-pass-baseline.json"))));report.addProperty("current_table_sha256",sha(Files.readAllBytes(LIVE)));report.addProperty("candidate_updates_sha256",sha(Files.readAllBytes(folder.resolve("updates.json"))));assertEquals(base,read(LIVE),"Live table changed during proof");report.add("occurrences",rows);EmeraldSourceStackFollowupsTest.save("towns-lavaridge-garden/runtime-proof.json",report);
    }

    @Test void lilycoveLampRecordsActualMixedElevationStackBeforeAnyMetadataOptIn()throws Exception{
        var source=EmeraldSourceStackFollowupsTest.source();SceneMap map=source.scene().map("EM_LILYCOVE_CITY");var levels=layout(map.id());var before=EmeraldSourceStackFollowupsTest.plan(map,source,read(ROOT.resolve("local/model-gallery/emerald-full-pass-baseline.json")),true,levels);var after=EmeraldSourceStackFollowupsTest.plan(map,source,read(LIVE),true,levels);assertEquals(CellKind.WALK,map.kind(61,33));assertEquals(CellKind.SOLID,map.kind(61,34));
        JsonObject proof=rectangle(map,61,33,1,2,before,after);JsonArray carriers=new JsonArray();for(int row=0;row<2;row++)for(int z=0;z<2;z++)for(int x=0;x<2;x++){int i=index(map,61,33+row,x,z);JsonObject c=new JsonObject();c.addProperty("row",row);c.addProperty("dx",x);c.addProperty("dz",z);c.addProperty("feet",levels==null?0:levels.level(61,33+row));c.addProperty("blocks",after.blocks()[i]);c.addProperty("decor",after.decor()[i]);c.addProperty("keys",Arrays.toString(after.open()[i]));carriers.add(c);}proof.add("carrier_audit",carriers);proof.addProperty("current_table_sha256",sha(Files.readAllBytes(LIVE)));JsonArray rows=new JsonArray();rows.add(proof);saveAt("lilycove-lamp-gallery/runtime-proof.json",rows);
    }
}
